{"results": [{"id": "hp_doc_bb56780bb06ee219b925b0cc21f04841fd291aaf146b229ae5edbd9b501bb322", "title": "Jack Fairbrother", "text": "John \"Jack\" Fairbrother (16 August 1917 – October 1999) was an English professional football goalkeeper, best known for his time at Newcastle United shortly after the Second World War. His uncle George Harrison played for Everton and England.", "score": 25.6786}, {"id": "hp_doc_f71bcf44483c62ba116764564a4826f380b0d6de59688fae0327e2a83b2c7436", "title": "Modbury Football Club", "text": "The Modbury Football Club (nicknamed The Hawks) is an Australian rules football club based in Modbury, a suburb of Adelaide in South Australia.", "score": 12.7173}, {"id": "hp_doc_a1b8f0e1b35cc14b6a40780350bf13280e9fa50da54f9af73d577392a8a51ac5", "title": "Leicester City W.F.C.", "text": "Leicester City Women Football Club is the official English women's football club affiliated with Leicester City F.C.. The club is distinct from \"Leicester City Ladies Football Club\" who are a stand-alone grassroots club. Leicester City Women won promotion back into the FA Women's Premier League Northern Division in 2016 winning a record 22 games out of 22.", "score": 12.084}], "remaining_searches": 2}
